import json

from taf.gnb.oam.coam.vdu.exceptions import ApiException
from taf.gnb.oam.coam.vdu.services.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.vdu.releases.vduoam25r3 import vDuOAM25R3
from taf.gnb.oam.coam.vdu.schemas.cp_config.reset_vdu_v1 import ResetVduCPCONFIGV1
from taf.gnb.oam.coam.vdu.services.agent_licensed.agent_licensed_v1 import AgentLicensedv1


class vDUOAM26R1(vDuOAM25R3):
    def __init__(self, con_details, need_all_info=False):
        super(vDUOAM26R1, self).__init__(con_details, need_all_info)
        self.agent_licensed = AgentLicensedv1(con_details=self.con_details)
        self.sec_v1 = SECv1(con_details=con_details)

    def search_parameter_of_current_plan(self, mo_dn, para_name, timeout=30):
        """
        After change made in https://gerrit.ext.net.nokia.com/gerrit/c/MN/MANO/OAMCU/SPEC/rest/+/8634025
        structure of complex parameter changed so that there is another level "value" in the structures
        change happened mid-release hence we try to process the response in the old way first and if it fails
        a new approach is taken.
        """
        response = self.emservice_v1.search_parameter_of_current_plan(para_name=para_name, timeout=timeout)
        try:
            return self._get_parameter_for_given_managed_object(
                response=response,
                mo_dn=mo_dn,
                parameter_name=para_name
            )

        except (KeyError, TypeError, IndexError):
            return self._get_parameter_for_given_managed_object_after_response_change(
                response=response,
                mo_dn=mo_dn,
                parameter_name=para_name
            )

    def _get_parameter_for_given_managed_object_after_response_change(self, response, mo_dn, parameter_name):
        main_parameter_name = parameter_name.split("/")[0]
        main_parameter = True if len(parameter_name.split("/")) == 1 else False

        for item in response["items"]:
            if item["distname"] == mo_dn and item["parameterName"] == main_parameter_name:
                if main_parameter:
                    return self._get_current_value_of_main_parameter_after_response_change(item)
                else:
                     return self._get_current_value_of_parameter_in_the_structure_after_response_change(
                         item=item, para_name=parameter_name
                     )

        raise ValueError(f"Parameter {parameter_name} for managed object {mo_dn} not found in the current plan.")

    @staticmethod
    def _get_current_value_of_main_parameter_after_response_change(item):
        """
        If user gives only main_parameter_name of the complex parameter, this function will be called.
        Therefore, it is needed to check if the given parameter is a list of other parameters or a single value.
        """
        parameter_value = json.loads(item["parameter"]["value"])
        try:
            if isinstance(parameter_value, list) and isinstance(parameter_value[0]["value"], list):
                return [parameter["value"] for parameter in parameter_value]

            return parameter_value["currentValue"]

        except TypeError:
            return [element["currentValue"] for element in parameter_value]

    @staticmethod
    def _get_current_value_of_parameter_in_the_structure_after_response_change(item, para_name):
        """
        If user gives only main_parameter_name and index, function will return whole object from given index.
        Otherwise, it will return the value of the parameter with the given name.
        """
        parameter_info = json.loads(item["parameter"]["value"])
        index = int(para_name.split("/")[1])

        if len(para_name.split("/")) == 2:
            return parameter_info[index]["value"]

        name = para_name.split("/")[2]
        for structure_index, structure_values in enumerate(parameter_info):
            if structure_index == index:
                for element in structure_values["value"]:
                    if element["name"] == name:
                        return json.loads(element["value"])["currentValue"]

    def reset_vdu(self, timeout=60, use_m2m=True, raw=False, **kwargs):
        """
        Manages vDU reset requests by adapting to the ongoing transition of M2M and internal endpoints from CP-CONFIG.

        As of 26R1, M2M endpoints for vDU reset have migrated to OAM-AGENT, and internal CP-CONFIG endpoints are
        scheduled for mid-release removal. For internal this method prioritizes CP-CONFIG requests and, if unsuccessful,
        uses OAM-AGENT.
        """
        if use_m2m:
            return self.agent_licensed.reset_vdu(timeout=timeout, **kwargs)

        else:
            try:
                response = self.cp_config.reset_vdu(timeout=timeout, **kwargs)
                return response if raw else ResetVduCPCONFIGV1.from_object_dict(response)

            except ApiException as e:
                if e.status == 404:
                    return self.agent_v1.reset_vdu(timeout=timeout, **kwargs)

                else:
                    raise

    def get_reset_vdu_operation_status(self, operation_id, timeout=30, use_m2m=True, raw=False):
        """
        Manages vDU reset operation status requests by adapting to the ongoing transition of M2M and internal
        endpoints from CP-CONFIG.

        As of 26R1, M2M endpoints for vDU reset have migrated to OAM-AGENT, and internal CP-CONFIG endpoints are
        scheduled for mid-release removal. For internal this method prioritizes CP-CONFIG requests and, if unsuccessful,
        uses OAM-AGENT.
        """
        if use_m2m:
            return self.agent_licensed.get_reset_vdu_operation_status(operation_id=operation_id, timeout=timeout)

        else:
            try:
                response = self.cp_config.get_reset_vdu_operation_status(operation_id=operation_id, timeout=timeout)
                return response if raw else ResetVduCPCONFIGV1.from_object_dict(response)

            except ApiException as e:
                if e.status == 404 and "No API found with those values API" in e.body:
                   return self.agent_v1.get_reset_vdu_operation_status(operation_id=operation_id, timeout=timeout)

                else:
                    raise

    def trigger_download_of_current_plan(self, include_auto_config_data=True, include_runtime_data=False, timeout=30,
                                         use_m2m=True):
        if use_m2m:
            return self.cm_licensed.download_current_plan(include_auto_config_data=include_auto_config_data,
                                                          include_runtime_data=include_runtime_data,
                                                          timeout=timeout)

        else:
            return self.cm.download_current_plan(include_auto_config_data=include_auto_config_data,
                                                 include_runtime_data=include_runtime_data,
                                                 timeout=timeout)

    def get_status_of_current_plan_download(self, operation_id, timeout=30, use_m2m=True):
        if use_m2m:
            return self.cm_licensed.get_download_plan_operation_status(operation_id=operation_id,
                                                                       timeout=timeout)

        else:
            return self.cm.get_download_plan_operation_status(operation_id=operation_id, timeout=timeout)

    def save_downloaded_plan_to_local(self, operation_id, path, timeout=30, use_m2m=True):
        if use_m2m:
            self.cm_licensed.get_downloaded_plan_file(operation_id=operation_id, path=path, timeout=timeout)

        else:
            self.cm.get_downloaded_plan_file(operation_id=operation_id, path=path, timeout=timeout)

    def start_5g_downlink_test(self, nrcell_id, test_model, beam_pattern_id, polarization, power_backoff, ru_mode,
                               phys_cell_id, codebook_2_antports, i11_codebook_4_antports, i2_codebook_4_antports,
                               i13_codebook_4_antports, mimo_rank, p_max, nrarfcn=0, timeout=60, nrarfcn_ul=0, nrarfcn_dl=0,
                               vswr_monitoring=False):
        return self.cp_config.start_5g_downlink_test(nrcell_id=nrcell_id,
                                                     test_model=test_model,
                                                     beam_pattern_id=beam_pattern_id,
                                                     polarization=polarization,
                                                     power_backoff=power_backoff,
                                                     ru_mode=ru_mode,
                                                     phys_cell_id=phys_cell_id,
                                                     codebook_2_antports=codebook_2_antports,
                                                     i11_codebook_4_antports=i11_codebook_4_antports,
                                                     i2_codebook_4_antports=i2_codebook_4_antports,
                                                     i13_codebook_4_antports=i13_codebook_4_antports,
                                                     mimo_rank=mimo_rank,
                                                     p_max=p_max,
                                                     nrarfcn=nrarfcn,
                                                     timeout=timeout,
                                                     nrarfcn_ul=nrarfcn_ul,
                                                     nrarfcn_dl=nrarfcn_dl,
                                                     vswr_monitoring=vswr_monitoring)

    def update_tx_power_thresholds(self, thresholds):
        return self.fh_v1.update_tx_power_thresholds(thresholds=thresholds)

    def check_secret_mode(self, timeout=30):
        return self.sec_v1.get_token_info(timeout=timeout)["UnpublishedDataMode"]
